namespace ghidra.trace.util;

using ghidra.docking.settings;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.listing;

public interface DataAdapterFromSettings : Data {

	T getSettingsDefinition<T>/* where T : SettingsDefinition */(
			Class<T> settingsDefinitionClass) {
		DataType dt = getBaseDataType();
		foreach (SettingsDefinition def in dt.getSettingsDefinitions()) {
			if (settingsDefinitionClass.isAssignableFrom(def.GetType())) {
				return settingsDefinitionClass.cast(def);
			}
		}
		return null;
	}

	bool hasMutability(int mutabilityType) {
		MutabilitySettingsDefinition def =
			getSettingsDefinition(typeof(MutabilitySettingsDefinition));
		if (def != null) {
			return def.getChoice(this) == mutabilityType;
		}
		return false;
	}

	/* @Override */
	bool isConstant() {
		return hasMutability(MutabilitySettingsDefinition.CONSTANT);
	}

	/* @Override */
	bool isWritable() {
		return hasMutability(MutabilitySettingsDefinition.WRITABLE);
	}

	/* @Override */
	bool isVolatile() {
		return hasMutability(MutabilitySettingsDefinition.VOLATILE);
	}
}
